import { useState, useEffect, useCallback } from 'react';
import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

const useNotifications = () => {
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [stats, setStats] = useState({
    total: 0,
    unread: 0,
    messages: 0,
    orders: 0,
    users: 0,
    system: 0,
    important: 0
  });

  // Récupérer le token
  const getToken = useCallback(() => {
    try {
      const token = localStorage.getItem('authToken');
      if (!token) return null;

      // Nettoyer le token
      let cleanToken = token.trim();
      if (cleanToken.startsWith('"') && cleanToken.endsWith('"')) {
        cleanToken = cleanToken.slice(1, -1);
      }
      if (cleanToken.startsWith("'") && cleanToken.endsWith("'")) {
        cleanToken = cleanToken.slice(1, -1);
      }

      return cleanToken;
    } catch (error) {
      console.error('❌ Erreur token:', error);
      return null;
    }
  }, []);

  // Créer instance axios
  const createAxiosInstance = useCallback(() => {
    const token = getToken();

    const instance = axios.create({
      baseURL: API_URL,
      timeout: 10000,
      headers: {
        'Content-Type': 'application/json',
        ...(token && { 'Authorization': `Bearer ${token}` })
      }
    });

    // Intercepteur pour les erreurs
    instance.interceptors.response.use(
      response => response,
      error => {
        console.error('❌ Erreur API:', error.response?.status, error.response?.data);

        if (error.response?.status === 401) {
          // Token expiré ou invalide
          setError('Session expirée. Veuillez vous reconnecter.');
          localStorage.removeItem('authToken');
          localStorage.removeItem('userData');
        }

        return Promise.reject(error);
      }
    );

    return instance;
  }, [getToken]);

  // Récupérer toutes les notifications
  const fetchNotifications = useCallback(async (options = {}) => {
    try {
      console.log('📥 fetchNotifications appelé');
      setLoading(true);
      setError(null);
      const axiosInstance = createAxiosInstance();

      const response = await axiosInstance.get('/notifications', {
        params: {
          limit: options.limit || 20,
          offset: options.offset || 0,
          unread_only: options.unreadOnly || false
        }
      });

      console.log('📨 Réponse fetchNotifications:', response.data);

      if (response.data.success) {
        setNotifications(response.data.notifications || []);
        return response.data.notifications;
      } else {
        throw new Error(response.data.message || 'Erreur lors du chargement des notifications');
      }
    } catch (err) {
      console.error('❌ Erreur fetchNotifications:', err);
      setError(err.response?.data?.message || err.message || 'Erreur lors du chargement des notifications');
      return [];
    } finally {
      setLoading(false);
    }
  }, [createAxiosInstance]);

  // Récupérer les statistiques
  const fetchNotificationStats = useCallback(async () => {
    try {
      console.log('📊 fetchNotificationStats appelé');
      const axiosInstance = createAxiosInstance();

      const response = await axiosInstance.get('/notifications/stats');

      console.log('✅ Réponse fetchNotificationStats:', response.data);

      if (response.data.success) {
        setStats(response.data.stats || {});
        return response.data.stats;
      } else {
        throw new Error(response.data.message || 'Erreur lors du chargement des statistiques');
      }
    } catch (err) {
      console.error('❌ Erreur fetchNotificationStats:', err);
      return {};
    }
  }, [createAxiosInstance]);

  // Marquer une notification comme lue
  const markAsRead = useCallback(async (notificationId) => {
    try {
      console.log('👁️ markAsRead appelé:', notificationId);
      const axiosInstance = createAxiosInstance();

      const response = await axiosInstance.patch(`/notifications/${notificationId}/read`);

      if (response.data.success) {
        // Mettre à jour localement
        setNotifications(prev => prev.map(notif => 
          notif.id === notificationId ? { ...notif, is_read: true } : notif
        ));

        // Mettre à jour les statistiques
        await fetchNotificationStats();

        return true;
      } else {
        throw new Error(response.data.message);
      }
    } catch (err) {
      console.error('❌ Erreur markAsRead:', err);
      return false;
    }
  }, [createAxiosInstance, fetchNotificationStats]);

  // Marquer toutes les notifications comme lues
  const markAllAsRead = useCallback(async () => {
    try {
      console.log('👁️ markAllAsRead appelé');
      const axiosInstance = createAxiosInstance();

      const response = await axiosInstance.patch('/notifications/read-all');

      if (response.data.success) {
        // Mettre à jour localement
        setNotifications(prev => prev.map(notif => ({ ...notif, is_read: true })));

        // Mettre à jour les statistiques
        await fetchNotificationStats();

        return true;
      } else {
        throw new Error(response.data.message);
      }
    } catch (err) {
      console.error('❌ Erreur markAllAsRead:', err);
      return false;
    }
  }, [createAxiosInstance, fetchNotificationStats]);

  // Supprimer une notification
  const deleteNotification = useCallback(async (notificationId) => {
    try {
      console.log('🗑️ deleteNotification appelé:', notificationId);
      const axiosInstance = createAxiosInstance();

      const response = await axiosInstance.delete(`/notifications/${notificationId}`);

      if (response.data.success) {
        // Supprimer localement
        setNotifications(prev => prev.filter(notif => notif.id !== notificationId));

        // Mettre à jour les statistiques
        await fetchNotificationStats();

        return true;
      } else {
        throw new Error(response.data.message);
      }
    } catch (err) {
      console.error('❌ Erreur deleteNotification:', err);
      return false;
    }
  }, [createAxiosInstance, fetchNotificationStats]);

  // Créer une notification (admin seulement)
  const createNotification = useCallback(async (notificationData) => {
    try {
      console.log('➕ createNotification appelé:', notificationData);
      const axiosInstance = createAxiosInstance();

      const response = await axiosInstance.post('/notifications', notificationData);

      if (response.data.success) {
        // Ajouter à la liste
        setNotifications(prev => [response.data.notification, ...prev]);

        // Mettre à jour les statistiques
        await fetchNotificationStats();

        return response.data.notification;
      } else {
        throw new Error(response.data.message);
      }
    } catch (err) {
      console.error('❌ Erreur createNotification:', err);
      throw err;
    }
  }, [createAxiosInstance, fetchNotificationStats]);

  // Créer des notifications de test
  const createTestNotifications = useCallback(async () => {
    try {
      console.log('🧪 createTestNotifications appelé');
      const axiosInstance = createAxiosInstance();

      const response = await axiosInstance.post('/notifications/test');

      if (response.data.success) {
        // Rafraîchir les notifications
        await fetchNotifications();
        await fetchNotificationStats();

        return true;
      } else {
        throw new Error(response.data.message);
      }
    } catch (err) {
      console.error('❌ Erreur createTestNotifications:', err);
      return false;
    }
  }, [createAxiosInstance, fetchNotifications, fetchNotificationStats]);

  // Fonction pour formater l'heure relative
  const formatTime = useCallback((dateString) => {
    if (!dateString) return 'À l\'instant';

    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now - date;
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return 'À l\'instant';
    if (diffMins < 60) return `Il y a ${diffMins} min`;
    if (diffHours < 24) return `Il y a ${diffHours} h`;
    if (diffDays === 1) return 'Hier';
    if (diffDays < 7) return `Il y a ${diffDays} j`;

    return date.toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' });
  }, []);

  // Fonction pour obtenir l'icône selon le type
  const getNotificationIcon = useCallback((type) => {
    switch (type) {
      case 'message': return '💬';
      case 'order': return '📦';
      case 'user': return '👤';
      case 'system': return '⚙️';
      case 'alert': return '⚠️';
      case 'success': return '✅';
      case 'warning': return '⚠️';
      default: return '🔔';
    }
  }, []);

  // Fonction pour obtenir la couleur selon le type
  const getNotificationColor = useCallback((type) => {
    switch (type) {
      case 'message': return 'bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400';
      case 'order': return 'bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400';
      case 'user': return 'bg-purple-100 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400';
      case 'system': return 'bg-amber-100 dark:bg-amber-900/30 text-amber-600 dark:text-amber-400';
      case 'alert': return 'bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400';
      case 'success': return 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400';
      case 'warning': return 'bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400';
      default: return 'bg-neutral-100 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-400';
    }
  }, []);

  // Fonction pour obtenir la couleur selon la priorité
  const getPriorityColor = useCallback((priority) => {
    switch (priority) {
      case 'critical': return 'bg-red-500 text-white';
      case 'high': return 'bg-orange-500 text-white';
      case 'medium': return 'bg-yellow-500 text-gray-800';
      case 'low': return 'bg-gray-500 text-white';
      default: return 'bg-gray-300 text-gray-800';
    }
  }, []);

  // Initialisation
  useEffect(() => {
    const token = getToken();
    if (token) {
      console.log('🔄 Initialisation useNotifications avec token');
      fetchNotifications();
      fetchNotificationStats();
    } else {
      console.log('❌ Pas de token trouvé pour useNotifications');
      setError('Veuillez vous connecter pour accéder aux notifications');
    }
  }, [getToken, fetchNotifications, fetchNotificationStats]);

  return {
    // États
    notifications,
    stats,
    loading,
    error,

    // Setters
    setError,

    // Fonctions principales
    fetchNotifications,
    fetchNotificationStats,
    markAsRead,
    markAllAsRead,
    deleteNotification,
    createNotification,
    createTestNotifications,

    // Fonctions utilitaires
    formatTime,
    getNotificationIcon,
    getNotificationColor,
    getPriorityColor
  };
};

export default useNotifications;
